using System;

namespace Thesis.Orchestration.Core
{
    // Identifier of one orchestrated session, generated by the queue authority when the queue runtime is
    // initialized and replicated with the queue state, so the exports of all participants of the same session
    // carry the same value. Run ids remain process-local; this is the key that joins them.
    // Survives queue-authority migration (the new authority keeps the replicated value).
    public static class SessionRunIdentity
    {
        public static string NewId() => $"S{DateTime.UtcNow:yyyyMMddTHHmmssZ}_{Guid.NewGuid():N}".Substring(0, 34);
    }
}
